            p.addCurve(to: CGPoint(x: 12, y: 8), control1: CGPoint(x: 17.3, y: 16), control2: CGPoint(x: 17.3, y: 8))
            p.closeSubpath()
        case .shield:
            p.move(to: CGPoint(x: 12, y: 2))
