            p.addQuadCurve(to: CGPoint(x: 12, y: 23), control: CGPoint(x: 18, y: 20))
            p.addQuadCurve(to: CGPoint(x: 4, y: 14), control: CGPoint(x: 6, y: 20))
            p.addLine(to: CGPoint(x: 3, y: 6))
            p.closeSubpath()
            p.move(to: CGPoint(x: 8, y: 12))
            p.addLine(to: CGPoint(x: 11, y: 15))
            p.addLine(to: CGPoint(x: 17, y: 9))
        case .report:
            p.move(to: CGPoint(x: 4, y: 22))
            p.addLine(to: CGPoint(x: 4, y: 3))
            p.addQuadCurve(to: CGPoint(x: 14, y: 3), control: CGPoint(x: 9, y: 0))
            p.addQuadCurve(to: CGPoint(x: 22, y: 3), control: CGPoint(x: 18, y: 6))
            p.addLine(to: CGPoint(x: 22, y: 14))
            p.addQuadCurve(to: CGPoint(x: 14, y: 14), control: CGPoint(x: 18, y: 17))
            p.addQuadCurve(to: CGPoint(x: 4, y: 14), control: CGPoint(x: 9, y: 11))
        case .block:
            p.move(to: CGPoint(x: 12, y: 2))
            p.addCurve(to: CGPoint(x: 12, y: 22), control1: CGPoint(x: -1.3, y: 2), control2: CGPoint(x: -1.3, y: 22))
            p.addCurve(to: CGPoint(x: 12, y: 2), control1: CGPoint(x: 25.3, y: 22), control2: CGPoint(x: 25.3, y: 2))
            p.closeSubpath()
            p.move(to: CGPoint(x: 5, y: 5))
            p.addLine(to: CGPoint(x: 19, y: 19))
        case .logout:
            p.move(to: CGPoint(x: 10, y: 3))
            p.addLine(to: CGPoint(x: 3, y: 3))
            p.addLine(to: CGPoint(x: 3, y: 21))
            p.addLine(to: CGPoint(x: 10, y: 21))
            p.move(to: CGPoint(x: 9, y: 12))
            p.addLine(to: CGPoint(x: 23, y: 12))
            p.move(to: CGPoint(x: 18, y: 7))
            p.addLine(to: CGPoint(x: 23, y: 12))
            p.addLine(to: CGPoint(x: 18, y: 17))
        case .refresh:
            p.move(to: CGPoint(x: 21, y: 9))
            p.addCurve(to: CGPoint(x: 3, y: 10), control1: CGPoint(x: 18, y: 0), control2: CGPoint(x: 5, y: 1))
            p.move(to: CGPoint(x: 21, y: 3))
            p.addLine(to: CGPoint(x: 21, y: 9))
            p.addLine(to: CGPoint(x: 15, y: 9))
            p.move(to: CGPoint(x: 3, y: 15))
            p.addCurve(to: CGPoint(x: 21, y: 14), control1: CGPoint(x: 6, y: 24), control2: CGPoint(x: 19, y: 23))
            p.move(to: CGPoint(x: 3, y: 21))
            p.addLine(to: CGPoint(x: 3, y: 15))
            p.addLine(to: CGPoint(x: 9, y: 15))
        case .chevronRight:
            p.move(to: CGPoint(x: 9, y: 4))
            p.addLine(to: CGPoint(x: 17, y: 12))
            p.addLine(to: CGPoint(x: 9, y: 20))
        }
        return p
    }
}

private struct KinnectGlyphShape: Shape {
    let glyph: KinnectGlyph
    func path(in rect: CGRect) -> Path {
        let scale = min(rect.width, rect.height) / 28
        let offsetX = (rect.width - 28 * scale) / 2 + 2 * scale + rect.minX
        let offsetY = (rect.height - 28 * scale) / 2 + 2 * scale + rect.minY
        return glyph.vector.applying(CGAffineTransform(a: scale, b: 0, c: 0, d: scale, tx: offsetX, ty: offsetY))
    }
}

/// Decorative glyph: put accessibilityLabel on the enclosing Button or Label.
struct KinnectIcon: View {
    let glyph: KinnectGlyph
    var size: CGFloat = 24
    var selected = false
    var tint: Color? = nil
    var body: some View {
        Group {
            if let tint = tint {
                KinnectGlyphShape(glyph: glyph)
                    .stroke(tint, style: StrokeStyle(lineWidth: (selected ? 2.05 : 1.65) * size / 28, lineCap: .round, lineJoin: .round))
            } else {
                KinnectGlyphShape(glyph: glyph)
                    .stroke(style: StrokeStyle(lineWidth: (selected ? 2.05 : 1.65) * size / 28, lineCap: .round, lineJoin: .round))
            }
        }
        .frame(width: size, height: size)
        .accessibilityHidden(true)
    }
}

/// Transparent chrome by default, including phone, videoCall and menu.
struct KinnectIconButton: View {
    let glyph: KinnectGlyph
    var label: String? = nil
    var size: CGFloat = 24
    var selected = false
    var tint: Color = .primary
    let action: () -> Void
    var body: some View {
        Button(action: action) {
            KinnectIcon(glyph: glyph, size: size, selected: selected, tint: tint)
                .frame(minWidth: 44, minHeight: 44)
                .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .accessibilityLabel(Text(label ?? glyph.label))
    }
}

